import{_ as a,o as i,c as t,ae as l}from"./chunks/framework.DCJ5T8RY.js";const _=JSON.parse('{"title":"PM2遇到的一个小问题","description":"","frontmatter":{"title":"PM2遇到的一个小问题","date":"2019-09-25"},"headers":[],"relativePath":"2019/pm2-issue.md","filePath":"2019/pm2-issue.md","lastUpdated":1786185344000}'),o={name:"2019/pm2-issue.md"};function s(r,e,n,d,p,c){return i(),t("div",null,[...e[0]||(e[0]=[l('<h3 id="写在前面" tabindex="-1">写在前面 <a class="header-anchor" href="#写在前面" aria-label="Permalink to &quot;写在前面&quot;">​</a></h3><p>这篇是大概一个半月前部署node项目时遇到的一个小问题，写下来备忘</p><h3 id="问题描述" tabindex="-1">问题描述 <a class="header-anchor" href="#问题描述" aria-label="Permalink to &quot;问题描述&quot;">​</a></h3><ol><li>部署完毕，运行报错的时候才发现服务器没有<code>pm2.config.js</code>配置的文件路径</li><li>ssh登陆服务器，准备手动建好文件路径，结果发现登陆账户权限不足...</li><li>迫于无奈，在登陆账户权限范围内新建了文件夹路径，同时改了pm2和nginx配置文件的路径</li><li>重启pm2和nginx，再运行不报错了</li><li>直接访问项目, 502</li><li>输入 <code>pm2 list</code>发现项目重启了500多次，最后还是挂了</li><li>搜了一下，找到了解决方案： <code>pm2 delete xxx</code>, 删了项目服务再重启</li><li>再次访问项目，ok了</li></ol><h3 id="原因" tabindex="-1">原因 <a class="header-anchor" href="#原因" aria-label="Permalink to &quot;原因&quot;">​</a></h3><p>pm2的配置文件某些配置项会有缓存，即使重启也没用，最好还是删了进程再重启</p><p>Done.</p>',7)])])}const h=a(o,[["render",s]]);export{_ as __pageData,h as default};
